//! One process-owned projector renderer, including actual retiring work.
use super::*;use crate::render_gpu::RenderGpu;use skylive_media::{RgbaFrame,MediaTime};use std::sync::{OnceLock,atomic::{AtomicBool,AtomicUsize,Ordering},mpsc::{self,SyncSender,Receiver}};
static OWNERS:AtomicUsize=AtomicUsize::new(0);struct Permit;impl Drop for Permit{fn drop(&mut self){OWNERS.fetch_sub(1,Ordering::AcqRel);}}
const OWNED_BYTES:usize=256*1024*1024;
struct Budget{bytes:AtomicUsize}
/// Retained CPU-delivery plus logical old/new display credit. Physical eGUI GPU
/// heaps/fences remain backend-owned; this is not a false native completion ack.
pub struct Lease{budget:Arc<Budget>,bytes:usize}
impl Lease{
 fn reserve(bytes:usize)->Result<Self,Error>{static BUDGET:OnceLock<Arc<Budget>>=OnceLock::new();let budget=BUDGET.get_or_init(||Arc::new(Budget{bytes:AtomicUsize::new(0)})).clone();budget.bytes.fetch_update(Ordering::AcqRel,Ordering::Acquire,|used|used.checked_add(bytes).filter(|sum|*sum<=OWNED_BYTES)).map_err(|_|Error::Busy)?;Ok(Self{budget,bytes})}
 fn split(&mut self,bytes:usize)->Result<Arc<Self>,Error>{if bytes>self.bytes{return Err(Error::Invalid("projector delivery credit footprint"));}self.bytes-=bytes;Ok(Arc::new(Self{budget:self.budget.clone(),bytes}))}
 pub fn charged_bytes(&self)->usize{self.bytes}
}
impl Drop for Lease{fn drop(&mut self){self.budget.bytes.fetch_sub(self.bytes,Ordering::AcqRel);}}
struct Work{request:Request,credit:Lease}
struct RawFrame{spec:Spec,image:RgbaFrame,next_after_ns:Option<u64>,tiles:Vec<TileStatus>}
pub struct Request {pub serial:u64,pub session:u64,pub model:Arc<StudioSnapshot>,pub playback:PlaybackSnapshot,pub capture:Arc<CaptureSnapshot>,pub resource_generation:u64,pub plans:Vec<Plan>}
#[derive(Clone)]pub struct TileStatus {pub tile:TileSnapshot,pub problem:Option<String>}
pub struct Frame<T=RgbaFrame> {pub spec:Spec,pub image:T,pub lease:Arc<Lease>,pub next_after_ns:Option<u64>,pub tiles:Vec<TileStatus>}
pub struct Reply<T=RgbaFrame> {pub serial:u64,pub session:u64,pub revision:u64,pub time:MediaTime,pub playback_epoch:u64,pub capture_epoch:u64,pub resource_generation:u64,pub frames:Result<Vec<Frame<T>>,Error>}
pub struct Worker<T:Send+'static=RgbaFrame> {send:Option<SyncSender<Work>>,receive:Receiver<Reply<T>>,closed:Arc<AtomicBool>,busy:bool,last_serial:u64}
impl Worker<RgbaFrame> {pub fn new(gpu:RenderGpu)->Result<Self,Error>{Self::new_with_image_adapter(gpu,|image|image)}}
impl<T:Send+'static> Worker<T> {
 /// Trusted composition-root pixel adapter executes on this same owner. The
 /// desktop adapter produces exactly4bytes/pixel; no GUI work or host UI dependency.
 pub fn new_with_image_adapter(gpu:RenderGpu,adapt:impl Fn(RgbaFrame)->T+Send+'static)->Result<Self,Error>{OWNERS.compare_exchange(0,1,Ordering::AcqRel,Ordering::Acquire).map_err(|_|Error::Busy)?;let permit=Permit;let(send,requests)=mpsc::sync_channel::<Work>(1);let(replies,receive)=mpsc::sync_channel(1);let closed=Arc::new(AtomicBool::new(false));let stopping=closed.clone();
  std::thread::Builder::new().name("projectors".into()).spawn(move||{let _permit=permit;let _services=crate::preview::retain_render_services();let mut renderer=gpu.output_renderer();let mut resource=None;while !stopping.load(Ordering::Acquire){let Work{request,mut credit}=match requests.recv_timeout(std::time::Duration::from_millis(8)){Ok(r)=>r,Err(mpsc::RecvTimeoutError::Timeout)=>continue,Err(_)=>break};let serial=request.serial;let session=request.session;let revision=request.model.revision();let time=request.playback.now();let playback_epoch=request.playback.epoch();let capture_epoch=request.capture.epoch();let generation=request.resource_generation;if resource!=Some(generation){renderer.resource_generation(generation);resource=Some(generation);}let result=render(&mut renderer,&request,&stopping);drop(request);if stopping.load(Ordering::Acquire){break;}let result=result.and_then(|frames|frames.into_iter().map(|frame|{let bytes=frame.image.byte_len().checked_mul(2).ok_or(Error::Invalid("projector delivery credit overflow"))?;let lease=credit.split(bytes)?;Ok(Frame{spec:frame.spec,image:adapt(frame.image),lease,next_after_ns:frame.next_after_ns,tiles:frame.tiles})}).collect());drop(credit);if stopping.load(Ordering::Acquire){break;}if replies.send(Reply{serial,session,revision,time,playback_epoch,capture_epoch,resource_generation:generation,frames:result}).is_err(){break;}}
  }).map_err(|e|Error::Backend(e.to_string()))?;
  Ok(Self{send:Some(send),receive,closed,busy:false,last_serial:0})
 }
 pub fn busy(&self)->bool{self.busy}
 pub fn submit(&mut self,request:Request)->Result<(),Error>{if self.closed.load(Ordering::Acquire){return Err(Error::Closed);}if self.busy{return Err(Error::Busy);}if request.serial<=self.last_serial||request.session!=request.playback.session()||request.model.revision()!=request.playback.revision()||request.capture.session()!=request.session||request.plans.is_empty()||request.plans.len()>MAX_WINDOWS||request.plans.iter().filter(|p|p.spec.target==Target::Multiview).count()>1||request.plans.iter().map(|p|p.tiles.len()).sum::<usize>()>30{return Err(Error::Invalid("projector request freshness/windows"));}let bytes=request.plans.iter().try_fold(0usize,|sum,p|sum.checked_add(p.spec.width as usize*p.spec.height as usize*4)).ok_or(Error::Invalid("projector atlas overflow"))?;if bytes>MAX_ATLAS_BYTES||request.plans.iter().any(|p|p.spec.width==0||p.spec.height==0||p.spec.width>1920||p.spec.height>1080||p.spec.session!=request.session||p.revision!=request.model.revision()||p.tiles.len()>27){return Err(Error::Invalid("projector atlas/tile limit"));}let mut ids=std::collections::HashSet::new();for plan in &request.plans{if plan.spec.id==0||plan.spec.epoch==0||!ids.insert(plan.spec.id){return Err(Error::Invalid("projector window identities"));}for tile in &plan.tiles{let r=tile.rect;if ![r.x,r.y,r.width,r.height].into_iter().all(f32::is_finite)||r.x<0.0||r.y<0.0||r.width<=0.0||r.height<=0.0||r.x+r.width>1.00001||r.y+r.height>1.00001||tile.basis.0==0||tile.basis.1==0||tile.basis.0>8192||tile.basis.1>8192||u64::from(tile.basis.0)*u64::from(tile.basis.1)>32*1024*1024{return Err(Error::Invalid("projector tile rectangles/dimensions"));}}}let serial=request.serial;let credit=Lease::reserve(bytes.checked_mul(3).ok_or(Error::Invalid("projector work credit overflow"))?)?;self.send.as_ref().ok_or(Error::Closed)?.try_send(Work{request,credit}).map_err(|_|Error::Busy)?;self.last_serial=serial;self.busy=true;Ok(())}
 pub fn poll(&mut self)->Result<Option<Reply<T>>,Error>{match self.receive.try_recv(){Ok(reply)=>{self.busy=false;Ok(Some(reply))},Err(mpsc::TryRecvError::Empty)=>Ok(None),Err(_)=>{self.busy=false;Err(Error::Closed)}}}
 pub fn close(&mut self){self.closed.store(true,Ordering::Release);self.send.take();}
}
impl<T:Send+'static> Drop for Worker<T>{fn drop(&mut self){self.close();}}
fn render(renderer:&mut crate::preview::OutputRenderer,request:&Request,closed:&AtomicBool)->Result<Vec<RawFrame>,Error>{let mut frames=Vec::new();for plan in &request.plans{if closed.load(Ordering::Acquire){return Err(Error::Closed);}let(w,h)=(plan.spec.width,plan.spec.height);let mut pixels=Vec::new();pixels.try_reserve_exact(w as usize*h as usize*4).map_err(|_|Error::Invalid("projector atlas allocation"))?;pixels.resize(w as usize*h as usize*4,0);for pixel in pixels.chunks_exact_mut(4){pixel[3]=255;}let mut statuses=Vec::new();let mut next_after_ns:Option<u64>=None;
 for tile in &plan.tiles{if closed.load(Ordering::Acquire){return Err(Error::Closed);}let rx=(tile.rect.x*w as f32).round()as u32;let ry=(tile.rect.y*h as f32).round()as u32;let rw=(tile.rect.width*w as f32).round().max(1.0)as u32;let rh=(tile.rect.height*h as f32).round().max(1.0)as u32;let inner=(rw.saturating_sub(4).max(1),rh.saturating_sub(4).max(1));let scale=(f64::from(inner.0)/f64::from(tile.basis.0)).min(f64::from(inner.1)/f64::from(tile.basis.1));let cw=(f64::from(tile.basis.0)*scale).round().max(1.0)as u32;let ch=(f64::from(tile.basis.1)*scale).round().max(1.0)as u32;
 let rendered=renderer.render_live(&request.model,&tile.output,cw,ch,&request.playback,&request.capture);let problem=match rendered{Ok(frame)=>{if let Some(after)=frame.next_after_ns{next_after_ns=Some(next_after_ns.map_or(after,|old|old.min(after)));}let x=rx+(rw.saturating_sub(cw))/2;let y=ry+(rh.saturating_sub(ch))/2;for row in 0..ch.min(h.saturating_sub(y)){let count=cw.min(w.saturating_sub(x))as usize*4;let a=row as usize*cw as usize*4;let b=((y+row)as usize*w as usize+x as usize)*4;pixels[b..b+count].copy_from_slice(&frame.image.pixels()[a..a+count]);}frame.diagnostics.first().map(|p|p.detail.clone())},Err(error)=>{eprintln!("Projector {} {:?}: {}",plan.spec.id,tile.role,error);Some(error.to_string())}};let problem=problem.map(|value|value.chars().take(4096).collect());statuses.push(TileStatus{tile:TileSnapshot{rect:tile.rect,role:tile.role,scene:tile.scene,label:tile.label.clone(),width:tile.basis.0,height:tile.basis.1},problem});
 }frames.push(RawFrame{spec:plan.spec,image:RgbaFrame::new(w,h,pixels).map_err(|e|Error::Backend(e.to_string()))?,next_after_ns,tiles:statuses});}Ok(frames)}
